#!/usr/bin/env node
/**
 * Writes plugin/test/data.generated.ts: the shared data files as string
 * constants, so the mod's own tests (run by `claude plugin test` in the
 * engine's module environment, where there is no file system and no JSON
 * import) can answer `$.fs.read` with the real files.
 *
 * Usage: node scripts/gen-plugin-data.mjs [--check]
 *   --check exits 1 when the generated file is out of date, for tests and CI.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('..', import.meta.url))
const out = `${root}plugin/test/data.generated.ts`

/** The generated module's text. */
export function generate() {
  const read = name => readFileSync(`${root}plugin/data/${name}`, 'utf8')
  return [
    '/**',
    ' * The shared data files as strings, for the mod\'s tests. Generated by',
    ' * scripts/gen-plugin-data.mjs from plugin/data; do not edit by hand.',
    ' */',
    '',
    `export const PRICES_JSON = ${JSON.stringify(read('prices.json'))}`,
    '',
    `export const RULES_JSON = ${JSON.stringify(read('rules.json'))}`,
    '',
    `export const STRINGS_JSON = ${JSON.stringify(read('strings.en.json'))}`,
    '',
  ].join('\n')
}

/** Whether this file was run directly, comparing paths case-insensitively on Windows. */
function isEntryPoint() {
  if (!process.argv[1]) return false
  const norm = (/** @type {string} */ p) => (process.platform === 'win32' ? resolve(p).toLowerCase() : resolve(p))
  return norm(fileURLToPath(import.meta.url)) === norm(process.argv[1])
}

if (isEntryPoint()) {
  const text = generate()
  if (process.argv.includes('--check')) {
    let current = ''
    try {
      current = readFileSync(out, 'utf8')
    } catch {}
    if (current !== text) {
      console.error('plugin/test/data.generated.ts is out of date: run node scripts/gen-plugin-data.mjs')
      process.exit(1)
    }
  } else {
    writeFileSync(out, text)
  }
}
